<?php
namespace Tests\Feature;
use App\Models\User;
use App\Models\Workspace;
use App\Services\Identity;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Carbon;
use Tests\TestCase;
class CrmTest extends TestCase {
 use RefreshDatabase;
 private function team():array{$o=User::factory()->create();$m=User::factory()->create();$a=User::factory()->create();$w=Workspace::create(['name'=>'Example','type'=>'business','owner_id'=>$o->id]);$w->members()->attach([$o->id=>['role'=>'owner'],$m->id=>['role'=>'manager'],$a->id=>['role'=>'member']]);return [$w,$o,$m,$a];}
 private function login(User $u,Workspace $w):static{return $this->actingAs($u)->withSession(['auth_version'=>$u->auth_version,'workspace_id'=>$w->id])->withoutVite();}
 private function contact():int{$this->post('/crm/contacts',['name'=>'Example contact','email'=>'example@example.test','lifecycle'=>'prospect'])->assertRedirect();return DB::table('crm_contacts')->latest('id')->value('id');}
 private function qualified(int $c):int{$this->post('/crm/leads',['contact_id'=>$c,'title'=>'Example opportunity','source'=>'Referral'])->assertRedirect();$id=DB::table('crm_leads')->latest('id')->value('id');$this->patch('/crm/leads/'.$id,['title'=>'Example opportunity','source'=>'Referral','status'=>'qualified','version'=>1])->assertRedirect();return $id;}
 private function deal(int $l,string $currency='USD'):int{$this->post('/crm/deals',['lead_id'=>$l,'title'=>'Example deal','currency'=>$currency,'amount'=>'99.95'])->assertRedirect();return DB::table('crm_deals')->latest('id')->value('id');}
 public function test_guest_personal_and_member_access_denied():void{$this->get('/crm')->assertRedirect('/login');[$w,$o,$m,$a]=$this->team();$this->login($o,Identity::personal($o))->get('/crm')->assertForbidden();$this->login($a,$w)->get('/crm')->assertForbidden();$this->post('/crm/contacts',['name'=>'Forbidden','lifecycle'=>'prospect'])->assertForbidden();$this->get('/dashboard')->assertOk()->assertDontSee('CRM &amp; sales',false);}
 public function test_company_contact_edit_segmentation_and_search():void{[$w,$o]=$this->team();$this->login($o,$w)->post('/crm/companies',['name'=>'Example agency','website'=>'https://example.test','segment'=>'Agency'])->assertRedirect();$id=DB::table('crm_companies')->value('id');$c=$this->contact();$this->put('/crm/contacts/'.$c,['name'=>'Updated client','company_id'=>$id,'lifecycle'=>'customer','segment'=>'Agency'])->assertRedirect();$this->get('/crm?segment=Agency&q=Updated')->assertOk()->assertSee('Updated client');$this->assertDatabaseHas('crm_contacts',['id'=>$c,'company_id'=>$id,'segment'=>'Agency']);$this->put('/crm/companies/'.$id,['name'=>'Invalid','website'=>'javascript:alert(1)'])->assertSessionHasErrors('website');}
 public function test_lead_assignment_and_conversion_once():void{[$w,$o,$m,$a]=$this->team();$this->login($o,$w);$c=$this->contact();$this->post('/crm/leads',['contact_id'=>$c,'title'=>'Denied','source'=>'Website','assignee_id'=>$a->id])->assertStatus(422);$l=$this->qualified($c);$this->patch('/crm/leads/'.$l,['title'=>'Stale','source'=>'Website','status'=>'qualified','version'=>1])->assertSessionHasErrors('version');$d=$this->deal($l);$this->post('/crm/deals',['lead_id'=>$l,'title'=>'Duplicate','currency'=>'USD','amount'=>'10'])->assertSessionHasErrors('lead_id');$this->assertDatabaseHas('crm_leads',['id'=>$l,'status'=>'converted']);$this->assertDatabaseHas('crm_deals',['id'=>$d,'amount'=>'99.95']);}
 public function test_pipeline_closing_and_currency_immutability():void{[$w,$o]=$this->team();$this->login($o,$w);$c=$this->contact();$d=$this->deal($this->qualified($c));$data=['title'=>'Won contract','amount'=>'100.25','stage'=>'won','version'=>1,'currency'=>'BDT'];$this->patch('/crm/deals/'.$d,$data)->assertRedirect();$this->assertDatabaseHas('crm_deals',['id'=>$d,'stage'=>'won','currency'=>'USD','version'=>2]);$this->assertDatabaseHas('crm_contacts',['id'=>$c,'lifecycle'=>'customer']);$this->patch('/crm/deals/'.$d,array_merge($data,['stage'=>'lost','version'=>2]))->assertSessionHasErrors('stage');}
 public function test_followups_and_due_dashboard():void{[$w,$o,$m]=$this->team();$this->travelTo(Carbon::parse('2026-11-27 12:00 UTC'));$this->login($o,$w);$l=$this->qualified($this->contact());$this->post('/crm/followups',['lead_id'=>$l,'user_id'=>$m->id,'title'=>'Call client','due_date'=>'2026-11-26'])->assertRedirect();$f=DB::table('crm_followups')->value('id');$this->get('/crm')->assertOk()->assertSee('Overdue')->assertSee('Call client');$this->patch('/crm/followups/'.$f,['completed'=>1])->assertRedirect();$this->assertNotNull(DB::table('crm_followups')->value('completed_at'));$this->patch('/crm/followups/'.$f,['completed'=>0])->assertRedirect();$this->assertNull(DB::table('crm_followups')->value('completed_at'));$this->get('/dashboard')->assertOk()->assertSee('CRM &amp; sales',false);}
 public function test_proposal_quotation_status_and_print():void{[$w,$o]=$this->team();$this->travelTo(Carbon::parse('2026-11-27 12:00 UTC'));$this->login($o,$w);$d=$this->deal($this->qualified($this->contact()));$data=['deal_id'=>$d,'kind'=>'quotation','title'=>'Example quote','body'=>'<script>alert(1)</script> Scope','amount'=>'25.10','valid_until'=>'2026-12-01','currency'=>'BDT'];$this->post('/crm/documents',$data)->assertRedirect();$id=DB::table('crm_documents')->value('id');$this->assertDatabaseHas('crm_documents',['id'=>$id,'currency'=>'USD','status'=>'draft']);$this->get('/crm/documents/'.$id)->assertOk()->assertSee('Example quote')->assertDontSee('<script>alert(1)</script>',false);$this->patch('/crm/documents/'.$id,['status'=>'accepted','version'=>1])->assertSessionHasErrors('status');$this->patch('/crm/documents/'.$id,['status'=>'sent','version'=>1])->assertRedirect();$this->patch('/crm/documents/'.$id,['status'=>'accepted','version'=>2])->assertRedirect();$this->assertDatabaseHas('crm_documents',['id'=>$id,'status'=>'accepted','version'=>3]);}
 public function test_interactions_escape_and_date_validation():void{[$w,$o]=$this->team();$this->travelTo(Carbon::parse('2026-11-27 12:00 UTC'));$this->login($o,$w);$c=$this->contact();$d=['contact_id'=>$c,'channel'=>'note','local_date'=>'2026-11-27','body'=>'<script>alert(1)</script> Client note'];$this->post('/crm/interactions',$d)->assertRedirect();$this->get('/crm')->assertOk()->assertSee('Client note')->assertDontSee('<script>alert(1)</script>',false)->assertSee('crm interactions created');$this->post('/crm/interactions',array_merge($d,['local_date'=>'2026-12-31']))->assertSessionHasErrors('local_date');}
 public function test_cross_workspace_records_and_relationships_denied():void{[$w,$o]=$this->team();$this->login($o,$w);$c=$this->contact();$l=$this->qualified($c);$d=$this->deal($l);$this->post('/crm/documents',['deal_id'=>$d,'kind'=>'proposal','title'=>'Private quote','body'=>'Secret scope','amount'=>'99'])->assertRedirect();$doc=DB::table('crm_documents')->value('id');[$other,$owner]=$this->team();$this->login($owner,$other)->get('/crm')->assertOk()->assertDontSee('Private quote')->assertDontSee('Example contact');$this->get('/crm/documents/'.$doc)->assertNotFound();$this->put('/crm/contacts/'.$c,['name'=>'Foreign','lifecycle'=>'customer'])->assertNotFound();$this->post('/crm/leads',['contact_id'=>$c,'title'=>'Foreign','source'=>'Website'])->assertNotFound();$this->post('/crm/documents',['deal_id'=>$d,'kind'=>'proposal','title'=>'Foreign','body'=>'No','amount'=>'10'])->assertNotFound();}
 public function test_demoted_and_removed_manager_denied():void{[$w,$o,$m]=$this->team();$this->login($m,$w)->get('/crm')->assertOk();$this->login($o,$w)->patch('/workspaces/'.$w->id.'/members/'.$m->id,['role'=>'member'])->assertRedirect();$this->login($m,$w)->get('/crm')->assertForbidden();$this->login($o,$w)->delete('/workspaces/'.$w->id.'/members/'.$m->id)->assertRedirect();$this->login($m,$w)->get('/crm')->assertForbidden();}
 public function test_analytics_separate_currencies_and_validates_precision():void{[$w,$o]=$this->team();$this->login($o,$w);$c=$this->contact();$this->deal($this->qualified($c),'USD');$this->deal($this->qualified($c),'BDT');$l=$this->qualified($c);$this->post('/crm/deals',['lead_id'=>$l,'title'=>'Invalid','currency'=>'USD','amount'=>'10.123'])->assertSessionHasErrors('amount');$this->get('/crm')->assertOk()->assertSee('USD 99.95')->assertSee('BDT 99.95');$stats=\App\Services\CrmAccess::stats($w,$o);$this->assertCount(2,$stats['totals']);}
}
